    'username': 'admin',
    'password': 'password123'
}

# HPP attack by adding duplicate parameters
hpp_params = {
    'username': 'admin',
    'password': 'wrongpass',
    'username': 'attacker',  # This will overwrite the first username in some implementations
    'password': 'password123'  # This will overwrite the second password in some implementations
}

# Send the request
